import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.D1JEzK2q.js";const g=JSON.parse('{"title":"Telegram","description":"","frontmatter":{},"headers":[],"relativePath":"channels/telegram.md","filePath":"channels/telegram.md"}'),o={name:"channels/telegram.md"};function n(r,e,d,l,c,h){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="telegram" tabindex="-1">Telegram <a class="header-anchor" href="#telegram" aria-label="Permalink to &quot;Telegram&quot;">​</a></h1><p>Telegram uses a bot token and long polling. No public webhook is required for chat delivery. One agent can answer in private chats, groups and supergroups.</p><h2 id="create-the-bot-and-get-its-token" tabindex="-1">Create the bot and get its token <a class="header-anchor" href="#create-the-bot-and-get-its-token" aria-label="Permalink to &quot;Create the bot and get its token&quot;">​</a></h2><p>You need a Telegram account and an existing gateway agent.</p><ol><li>Open the verified <a href="https://t.me/BotFather" target="_blank" rel="noreferrer">BotFather</a> account in Telegram.</li><li>Send <code>/newbot</code>, choose a display name, then a unique username ending in <code>bot</code>.</li><li>Copy the issued bot token. It authenticates the bot and must stay private. BotFather can generate a replacement if it is exposed.</li></ol><p>These are Telegram&#39;s <a href="https://core.telegram.org/bots/tutorial#obtain-your-bot-token" target="_blank" rel="noreferrer">official bot creation instructions</a>.</p><h2 id="connect-the-agent" tabindex="-1">Connect the agent <a class="header-anchor" href="#connect-the-agent" aria-label="Permalink to &quot;Connect the agent&quot;">​</a></h2><p>Run <code>claude-gateway agents update --agent assistant</code>, select Telegram, and paste the token. For configuration managed as a file, add this fragment to the existing agent:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;telegram&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;botToken&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;\${TELEGRAM_BOT_TOKEN}&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Supply <code>TELEGRAM_BOT_TOKEN</code> to the gateway process environment. The environment variable name is your choice; the <code>\${...}</code> reference is what connects it to <code>telegram.botToken</code>. Manual file edits require a gateway restart. The management API uses <code>telegram_bot_token</code> in <code>PATCH /api/v1/agents/:agentId</code>; that snake-case field is an API payload field, not the configuration key.</p><p>Run only one polling receiver for each bot token. If the bot previously used a webhook, remove that webhook using Telegram&#39;s <code>deleteWebhook</code> API before starting polling. Telegram does not allow <code>getUpdates</code> while a webhook is configured. See <a href="https://core.telegram.org/bots/api#getupdates" target="_blank" rel="noreferrer">Telegram Bot API delivery methods</a>.</p><h2 id="pair-your-private-chat" tabindex="-1">Pair your private chat <a class="header-anchor" href="#pair-your-private-chat" aria-label="Permalink to &quot;Pair your private chat&quot;">​</a></h2><p>Open the bot&#39;s Telegram profile, press <strong>Start</strong>, and send a message. For a new agent, the bot sends a six-character pairing code. Approve it from your gateway terminal:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> channels</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pending</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> assistant</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --channel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> telegram</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> channels</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> approve</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> assistant</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --channel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> telegram</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --code</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> YOUR_CODE</span></span></code></pre></div><p>Send a second message and confirm that the agent answers. This tests both delivery and access. <code>/status</code> reports pairing status. To stop inviting new senders after setup, turn pairing off in channel settings; existing approved senders remain allowed.</p><h2 id="group-setup" tabindex="-1">Group setup <a class="header-anchor" href="#group-setup" aria-label="Permalink to &quot;Group setup&quot;">​</a></h2><ol><li>Add the bot to the group.</li><li>Ensure Telegram delivers messages: promote the bot to an administrator, or use BotFather&#39;s <code>/setprivacy</code> to disable Privacy Mode, then remove and re-add the bot. Telegram documents default privacy behavior and administrator exceptions in <a href="https://core.telegram.org/bots/features#privacy-mode" target="_blank" rel="noreferrer">bot features</a>.</li><li>With <code>groupPolicy: &quot;allowlist&quot;</code> and <code>pairing: true</code>, send a plain group message. The bot posts a pairing code in the group.</li><li>Inspect the pending request and approve the code using the CLI above. A group request adds the group ID to <code>groupAllowlist</code>.</li><li>Mention the bot&#39;s username or reply to one of its messages to trigger a response when <code>requireMention</code> is true.</li></ol><p>A message filtered by Telegram cannot initiate pairing. Gateway bot commands are DM-only and are dropped in groups, so use a plain message after configuring delivery. Turning <code>requireMention</code> off only helps if Telegram actually delivers all group messages.</p><h2 id="access-configuration" tabindex="-1">Access configuration <a class="header-anchor" href="#access-configuration" aria-label="Permalink to &quot;Access configuration&quot;">​</a></h2><p>Telegram credentials live in <code>config.json</code>; active access rules live at <code>&lt;workspace&gt;/.telegram-state/access.json</code>. The normal workspace is <code>~/.claude-gateway/agents/assistant/workspace</code>.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;dmPolicy&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;allowlist&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;pairing&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;allowFrom&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;groupPolicy&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;allowlist&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;groupAllowlist&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;requireMention&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Use string Telegram user IDs in <code>allowFrom</code> and string chat IDs in <code>groupAllowlist</code>; obtain them from the pending request or gateway channel settings. Group IDs are usually negative. These are stable IDs, not display names or bot tokens. Preserve existing approvals and pending state when editing an existing file.</p><p><code>requireMention</code> is one top-level setting for groups. The receiver rereads access rules on inbound messages. Legacy <code>dmPolicy: &quot;pairing&quot;</code> becomes <code>dmPolicy: &quot;allowlist&quot;</code> plus <code>pairing: true</code>. Older per-group <code>groups</code> maps migrate to the flat schema; historical member restrictions may remain in <code>legacyGroupAllowFrom</code>. Use the flat schema for new setups.</p><p>In an agent session with the Telegram access skill installed, <code>/telegram:access pair &lt;code&gt;</code> approves a request, <code>/telegram:access pairing off</code> disables invitations, and <code>/telegram:access group mention &lt;on|off&gt;</code> changes the mention gate. These are agent-session skill commands, distinct from commands sent to the Telegram bot.</p><h2 id="private-chat-commands" tabindex="-1">Private-chat commands <a class="header-anchor" href="#private-chat-commands" aria-label="Permalink to &quot;Private-chat commands&quot;">​</a></h2><p>Once paired, use these commands in the bot&#39;s private chat:</p><table tabindex="0"><thead><tr><th>Command</th><th>Behavior</th></tr></thead><tbody><tr><td><code>/start</code>, <code>/status</code>, <code>/help</code></td><td>Pairing instructions, pairing status, available commands</td></tr><tr><td><code>/session</code></td><td>Current session name, message count and context usage</td></tr><tr><td><code>/sessions</code></td><td>List, switch or delete sessions using buttons</td></tr><tr><td><code>/new &lt;name&gt;</code></td><td>Create a session; name is optional</td></tr><tr><td><code>/rename &lt;name&gt;</code></td><td>Rename the current session</td></tr><tr><td><code>/clear</code></td><td>Clear history after confirmation</td></tr><tr><td><code>/compact</code></td><td>Summarize older history</td></tr><tr><td><code>/stop</code></td><td>Interrupt the active turn</td></tr><tr><td><code>/restart</code></td><td>Confirm a graceful session restart</td></tr><tr><td><code>/model</code></td><td>Show the current model</td></tr><tr><td><code>/models</code></td><td>Open the model picker; selecting restarts sessions, Dismiss cancels</td></tr></tbody></table><p>The model list comes from the configured model provider&#39;s <code>/v1/models</code> catalog when available, with <code>gateway.models</code> as fallback. Changing an agent model affects its other chats too.</p><h2 id="voice-notes-and-background-tasks" tabindex="-1">Voice notes and background tasks <a class="header-anchor" href="#voice-notes-and-background-tasks" aria-label="Permalink to &quot;Voice notes and background tasks&quot;">​</a></h2><p>With <code>gateway.orchestration: true</code>, Telegram voice notes and audio attachments can use the agent&#39;s configured speech-to-text provider. Enable <code>agents[].voice</code> and its <code>notes</code> settings first; see <a href="/claude-gateway/guide/voice.html">voice setup</a> for provider keys, models and prerequisites. Photos and file attachments keep their normal access checks.</p><p>In a paired private chat, <code>/voice</code> opens Always / Only reply voice message / Off buttons. <code>/voice on</code>, <code>/voice auto</code> and <code>/voice off</code> also set the mode directly. Every chat starts Off, and its choice persists across session switches and gateway restarts. <code>auto</code> adds audio to replies originating from voice input and their task results; a later typed instruction makes that turn text-only. <code>/voices</code> selects a voice through a paginated provider catalog. Agent voice must be enabled and <code>voice.notes.replyWithVoice</code> must permit spoken replies. Voice capability and chat preference are separate settings.</p><p><code>/tasks</code> opens the current session&#39;s pending work, ten tasks per page. Open a task for status, progress, a pending question or task-specific stop. The browser refreshes automatically; Back and Dismiss do not cancel work or call a model. <code>/session</code> and <code>/sessions</code> also act as direct gateway controls in orchestration mode. Typing reflects queued inputs, active agent work and workers, stopping when only user-input/reconciliation waits remain. See <a href="/claude-gateway/guide/orchestration.html">orchestration</a>.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Check</th></tr></thead><tbody><tr><td><code>401 Unauthorized</code></td><td>Token belongs to this bot and has not been revoked; update it after a BotFather reset</td></tr><tr><td><code>409 Conflict</code></td><td>Another gateway, development process or old deployment is polling the same token; keep one receiver</td></tr><tr><td>No private reply</td><td>Bot was started, request approved, DM policy enabled, agent execution working</td></tr><tr><td>Private chat works, group silent</td><td>Privacy Mode/admin status, remove/re-add after privacy changes, group approval, mention gate</td></tr><tr><td><code>/start</code> does nothing in a group</td><td>Commands are DM-only; pair using a normal delivered group message</td></tr><tr><td>Missing environment variable at startup</td><td>Token variable must exist in the gateway service environment</td></tr></tbody></table><p>Implementation references: <a href="https://github.com/0xMaxMa/claude-gateway/blob/b917843/src/telegram/receiver.ts" target="_blank" rel="noreferrer">receiver</a>, <a href="https://github.com/0xMaxMa/claude-gateway/blob/b917843/src/types.ts" target="_blank" rel="noreferrer">configuration types</a>, and <a href="https://github.com/0xMaxMa/claude-gateway/blob/b917843/src/api/router.ts" target="_blank" rel="noreferrer">access/API handling</a>.</p>`,35)])])}const u=t(o,[["render",n]]);export{g as __pageData,u as default};
